import logging
from taf.collectors.aashell_cli.factory import AaShellCliFactory
from taf.collectors.core import core

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class aashell_cli(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def create_aashell_cli(self,
                           name,
                           host=None,
                           port=None,
                           hops=None,
                           forwarding_port=None):
        """
        Create an Aashell CLI from given configuration

        :param str name: name of collector
        :param str host: AaShell host IP address, default value is "127.0.0.1"
        :param int port: AaShell port, default value is 15007
        :param dict hops: (optional) intermediate hops (host, user, password, pkey, key_filename, port, proxy
            (previous hop if applicable)) needed to reach AaShell service, default value is None
        :param int forwarding_port: (optional) local port in test VM where forwarding will be done
            (localhost:forwarding_port <- host:port). By default it will use port value
        """
        configuration = {}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["host", "port", "hops", "forwarding_port"]:
                if parameter_value is not None:
                    configuration[parameter_name] = int(parameter_value) \
                        if parameter_name in ["port", "forwarding_port"] else parameter_value
        logger.info("Creating Aashell CLI with alias name :" + name)
        aashell_cli = AaShellCliFactory().create(configuration=configuration, existing_arguments={})
        logger.info("Aashell CLI created successfully")
        self.set_alias(name, aashell_cli)
